customCSS:
.t, .history { color: #626262; }
.join { color: #5f865f; }
.part, .quit { color: #626262; }
.kick, .error { color: #d68787; }
.notice { color: #d8af5f; }
.action { color: #d7afaf; }
.mode, .nick, .topic, .server { color: #87afaf; }
.highlight { color: #d0d0d0; background-color: #005f5f; border-left: 3px solid #d7afaf; padding-left: 8px; }
.reply { color: #626262; border-left: 2px solid #85add4; padding-left: 6px; }
.oper { color: #3a3a3a; background-color: #d8af5f; }
.reactions { color: #85add4; background-color: #4e4e4e; }
.card { background-color: #4e4e4e; border-color: #626262; }
.card-title { color: #85add4; }
.card-desc { color: #626262; }
.daychange { color: #626262; border-color: #4e4e4e; }
